1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
ftrace: Do not over-allocate ftrace memory

The pg_remaining calculation in ftrace_process_locs() assumes that
ENTRIES_PER_PAGE multiplied by 2^order equals the actual capacity of the
allocated page group. However, ENTRIES_PER_PAGE is PAGE_SIZE / ENTRY_SIZE
(integer division). When PAGE_SIZE is not a multiple of ENTRY_SIZE (e.g.
4096 / 24 = 170 with remainder 16), high-order allocations (like 256 pages)
have significantly more capacity than 256 * 170. This leads to pg_remaining
being underestimated, which in turn makes skip (derived from skipped -
pg_remaining) larger than expected, causing the WARN(skip != remaining)
to trigger.

Extra allocated pages for ftrace: 2 with 654 skipped
WARNING: CPU: 0 PID: 0 at kernel/trace/ftrace.c:7295 ftrace_process_locs+0x5bf/0x5e0

A similar problem in ftrace_allocate_records() can result in allocating
too many pages. This can trigger the second warning in
ftrace_process_locs().

Extra allocated pages for ftrace
WARNING: CPU: 0 PID: 0 at kernel/trace/ftrace.c:7276 ftrace_process_locs+0x548/0x580

Use the actual capacity of a page group to determine the number of pages
to allocate. Have ftrace_allocate_pages() return the number of allocated
pages to avoid having to calculate it. Use the actual page group capacity
when validating the number of unused pages due to skipped entries.
Drop the definition of ENTRIES_PER_PAGE since it is no longer used.

Cc: stable@vger.kernel.org
Fixes: 4a3efc6baff93 ("ftrace: Update the mcount_loc check of skipped entries")
Link: https://patch.msgid.link/20260113152243.3557219-1-linux@roeck-us.net
Signed-off-by: Guenter Roeck <linux@roeck-us.net>
Signed-off-by: Steven Rostedt (Google) <rostedt@goodmis.org>

Here is the root cause:
The bug is caused by using the macro ENTRIES_PER_PAGE (defined as PAGE_SIZE / ENTRY_SIZE, integer division) to estimate both the capacity of allocated page groups and the number of pages needed. When PAGE_SIZE is not a multiple of ENTRY_SIZE, the actual entry capacity of a multi-page group (e.g., (PAGE_SIZE << order) / ENTRY_SIZE) is larger than the estimate based on ENTRIES_PER_PAGE. This leads to underestimation of pg_remaining (remaining entries in the last page group) and over-allocation of pages, triggering the two warnings in ftrace_process_locs().

Here is the patch:

 #define ENTRY_SIZE sizeof(struct dyn_ftrace)
-#define ENTRIES_PER_PAGE (PAGE_SIZE / ENTRY_SIZE)

 static struct ftrace_page	*ftrace_pages_start;

-static int ftrace_allocate_records(struct ftrace_page *pg, int count)
+static int ftrace_allocate_records(struct ftrace_page *pg, int count,
+				   unsigned long *num_pages)
 {
 	int order;
 	int pages;
 	int cnt;

 	if (WARN_ON(!count))
 		return -EINVAL;

 	/* We want to fill as much as possible, with no empty pages */
-	pages = DIV_ROUND_UP(count, ENTRIES_PER_PAGE);
+	pages = DIV_ROUND_UP(count * ENTRY_SIZE, PAGE_SIZE);
 	order = fls(pages) - 1;

  again:
 	pg->records = (void *)__get_free_pages(GFP_KERNEL | __GFP_ZERO, order);

 	if (!pg->records) {
 		/* if we can't allocate this size, try something smaller */
 		if (!order)
 			return -ENOMEM;
 		order--;
 		goto again;
 	}

 	ftrace_number_of_pages += 1 << order;
+	*num_pages += 1 << order;
 	ftrace_number_of_groups++;

 	cnt = (PAGE_SIZE << order) / ENTRY_SIZE;
 	pg->order = order;

 	if (cnt > count)
 		cnt = count;

 	return cnt;
 }


 static struct ftrace_page *
-ftrace_allocate_pages(unsigned long num_to_init)
+ftrace_allocate_pages(unsigned long num_to_init, unsigned long *num_pages)
 {
 	struct ftrace_page *start_pg;
 	struct ftrace_page *pg;
 	int cnt;

+	*num_pages = 0;
+
 	if (!num_to_init)
 		return NULL;

 	start_pg = pg = kzalloc(sizeof(*pg), GFP_KERNEL);
 	if (!pg)
 		return NULL;

 	/*
 	 * Try to allocate as much as possible in one continues
 	 * location that fills in all of the space. We want to
 	 * waste as little space as possible.
 	 */
 	for (;;) {
-		cnt = ftrace_allocate_records(pg, num_to_init);
+		cnt = ftrace_allocate_records(pg, num_to_init, num_pages);
 		if (cnt < 0)
 			goto free_pages;

 		num_to_init -= cnt;
 		if (!num_to_init)
 			break;

 		pg->next = kzalloc(sizeof(*pg), GFP_KERNEL);
 		if (!pg->next)
 			goto free_pages;

 		pg = pg->next;
 	}

 	return start_pg;

  free_pages:
 	ftrace_free_pages(start_pg);
 	pr_info("ftrace: FAILED to allocate memory for functions\n");
 	return NULL;
 }


 static int ftrace_process_locs(struct module *mod,
 			       unsigned long *start,
 			       unsigned long *end)
 {
 	struct ftrace_page *pg_unuse = NULL;
 	struct ftrace_page *start_pg;
 	struct ftrace_page *pg;
 	struct dyn_ftrace *rec;
 	unsigned long skipped = 0;
 	unsigned long count;
 	unsigned long *p;
 	unsigned long addr;
 	unsigned long flags = 0; /* Shut up gcc */
 	unsigned long pages;
 	int ret = -ENOMEM;

 	count = end - start;

 	if (!count)
 		return 0;

-	pages = DIV_ROUND_UP(count, ENTRIES_PER_PAGE);
-
 	/*
 	 * Sorting mcount in vmlinux at build time depend on
 	 * CONFIG_BUILDTIME_MCOUNT_SORT, while mcount loc in
 	 * modules can not be sorted at build time.
 	 */
 	if (!IS_ENABLED(CONFIG_BUILDTIME_MCOUNT_SORT) || mod) {
 		sort(start, count, sizeof(*start),
 		     ftrace_cmp_ips, NULL);
 	} else {
 		test_is_sorted(start, count);
 	}

-	start_pg = ftrace_allocate_pages(count);
+	start_pg = ftrace_allocate_pages(count, &pages);
 	if (!start_pg)
 		return -ENOMEM;

 	mutex_lock(&ftrace_lock);

 	/*
 	 * Core and each module needs their own pages, as
 	 * modules will free them when they are removed.
 	 * Force a new page to be allocated for modules.
 	 */
 	if (!mod) {
 		WARN_ON(ftrace_pages || ftrace_pages_start);
 		/* First initialization */
 		ftrace_pages = ftrace_pages_start = start_pg;
 	} else {
 		if (!ftrace_pages)
 			goto out;

 		if (WARN_ON(ftrace_pages->next)) {
 			/* Hmm, we have free pages? */
 			while (ftrace_pages->next)
 				ftrace_pages = ftrace_pages->next;
 		}

 		ftrace_pages->next = start_pg;
 	}

 	p = start;
 	pg = start_pg;
 	while (p < end) {
 		unsigned long end_offset;

 		addr = *p++;

 		/*
 		 * Some architecture linkers will pad between
 		 * the different mcount_loc sections of different
 		 * object files to satisfy alignments.
 		 * Skip any NULL pointers.
 		 */
 		if (!addr) {
 			skipped++;
 			continue;
 		}

 		/*
 		 * If this is core kernel, make sure the address is in core
 		 * or inittext, as weak functions get zeroed and KASLR can
 		 * move them to something other than zero. It just will not
 		 * move it to an area where kernel text is.
 		 */
 		if (!mod && !(is_kernel_text(addr) || is_kernel_inittext(addr))) {
 			skipped++;
 			continue;
 		}

 		addr = ftrace_call_adjust(addr);

 		end_offset = (pg->index+1) * sizeof(pg->records[0]);
 		if (end_offset > PAGE_SIZE << pg->order) {
 			/* We should have allocated enough */
 			if (WARN_ON(!pg->next))
 				break;
 			pg = pg->next;
 		}

 		rec = &pg->records[pg->index++];
 		rec->ip = addr;
 	}

 	if (pg->next) {
 		pg_unuse = pg->next;
 		pg->next = NULL;
 	}

 	/* Assign the last page to ftrace_pages */
 	ftrace_pages = pg;

 	/*
 	 * We only need to disable interrupts on start up
 	 * because we are modifying code that an interrupt
 	 * may execute, and the modification is not atomic.
 	 * But for modules, nothing runs the code we modify
 	 * until we are finished with it, and there's no
 	 * reason to cause large interrupt latencies while we do it.
 	 */
 	if (!mod)
 		local_irq_save(flags);
 	ftrace_update_code(mod, start_pg);
 	if (!mod)
 		local_irq_restore(flags);
 	ret = 0;
  out:
 	mutex_unlock(&ftrace_lock);

 	/* We should have used all pages unless we skipped some */
 	if (pg_unuse) {
 		unsigned long pg_remaining, remaining = 0;
-		unsigned long skip;
+		long skip;

 		/* Count the number of entries unused and compare it to skipped. */
-		pg_remaining = (ENTRIES_PER_PAGE << pg->order) - pg->index;
+		pg_remaining = (PAGE_SIZE << pg->order) / ENTRY_SIZE - pg->index;

 		if (!WARN(skipped < pg_remaining, "Extra allocated pages for ftrace")) {

 			skip = skipped - pg_remaining;

-			for (pg = pg_unuse; pg; pg = pg->next)
+			for (pg = pg_unuse; pg && skip > 0; pg = pg->next) {
 				remaining += 1 << pg->order;
+				skip -= (PAGE_SIZE << pg->order) / ENTRY_SIZE;
+			}

 			pages -= remaining;

-			skip = DIV_ROUND_UP(skip, ENTRIES_PER_PAGE);
-
 			/*
 			 * Check to see if the number of pages remaining would
 			 * just fit the number of entries skipped.
 			 */
-			WARN(skip != remaining, "Extra allocated pages for ftrace: %lu with %lu skipped",
+			WARN(pg || skip > 0, "Extra allocated pages for ftrace: %lu with %lu skipped",
 			     remaining, skipped);
 		}
 		/* Need to synchronize with ftrace_location_range() */
 		synchronize_rcu();
 		ftrace_free_pages(pg_unuse);
 	}

 	if (!mod) {
 		count -= skipped;
 		pr_info("ftrace: allocating %ld entries in %ld pages\n",
 			count, pages);
 	}

 	return ret;
 }



